package glitch

import data.glitch_lib

protocol_keys := {"protocol", "endpoint", "url", "source", "baseurl", "mirrorlist", "load_balancer_protocol", "api_gateway_protocol"}
security_keys := {"encryption", "tls_version", "ssl_policy", "secure_transfer", "checksum_validation", "use_ssl"}
bool_false := {"false", false}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    attr.name in protocol_keys
    attr.value.ir_type == "String"
    lower_value := lower(attr.value.value)
    lower_value == "http"

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing Support for Integrity Check - Using plaintext protocols (e.g., HTTP) without integrity validation. (CWE-353)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    attr.name in security_keys
    check_security_false(attr.value)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing Support for Integrity Check - Configuration disables integrity features (e.g., encryption, TLS). (CWE-353)"
    }
}

check_security_false(value) {
    value.ir_type == "String"
    lower(value.value) in bool_false
} else {
    value.ir_type == "Boolean"
    value.value == false
}

